"""Generate src/mcp-server/tool-catalog.ts from the recorded upstream tools/list.

Usage: python3 tests/fixtures/generate/mcp_tool_catalog.py tests/fixtures/mcp/wire.json > src/mcp-server/tool-catalog.ts

The upstream schemas are pydantic-generated; this copies them verbatim except
for the version payload, whose runtime block is adapted for this port
(`runtime.python` -> `runtime.name` + `runtime.version`) and which also
carries `upstream_spec_kit_version`.
"""
import copy
import json
import sys

wire = json.load(open(sys.argv[1], encoding="utf-8"))
tools = next(e for e in wire if e["label"] == "tools-list")["response"]["result"]["tools"]
tools = copy.deepcopy(tools)


def adapt_version_schema(schema, runtime_def):
    props = schema["properties"]
    new_props = {"cli_version": props["cli_version"],
                 "upstream_spec_kit_version": {"title": "Upstream Spec Kit Version", "type": "string"}}
    for key, value in props.items():
        if key != "cli_version":
            new_props[key] = value
    schema["properties"] = new_props
    req = schema["required"]
    schema["required"] = [req[0], "upstream_spec_kit_version", *req[1:]]
    runtime = schema["$defs"][runtime_def]
    rp = runtime["properties"]
    runtime["properties"] = {
        "name": {"title": "Name", "type": "string"},
        "version": {"title": "Version", "type": "string"},
        "openssl": rp["openssl"],
    }
    runtime["required"] = ["name", "version", "openssl"]


for tool in tools:
    if tool["name"] == "specify_version":
        adapt_version_schema(tool["outputSchema"], "VersionRuntimeResult")
    elif tool["name"] == "specify_run_command":
        adapt_version_schema(tool["outputSchema"], "RuntimeInfo")

print('''/**
 * @oakoliver/specify-cli - MCP tool catalog (generated)
 *
 * GENERATED by tests/fixtures/generate/mcp_tool_catalog.py from the
 * `tools/list` response of upstream spec-kit v1.2.5 `specify mcp`
 * (pydantic-generated schemas, verbatim). ADAPTATION: the version payload
 * schemas report `runtime.name` + `runtime.version` instead of
 * `runtime.python`, plus `upstream_spec_kit_version`.
 *
 * @module mcp-server/tool-catalog
 */

/* eslint-disable */
export const MCP_TOOLS: ReadonlyArray<Record<string, unknown>> = ''' + json.dumps(tools, indent=2, ensure_ascii=False) + ''';
''')
